// This file is generated by AI.

// 耗时估算规则测试。
//
// 这里钉住四件事:
// 1. **按采样步数分桶** —— 不同步数互不污染 (x4 的快不能拿来说 x32);
// 2. 样本不足时用"先验形状 × 修正系数", 一个样本就能整体纠偏;
// 3. 样本够了以后用最小二乘拟合;
// 4. **只剔除偏高的离群值** —— 一次被系统拖慢的推理不该长期污染预估。

import { describe, expect, it } from 'vitest';

import { DurationEstimator, type SampleStorage } from '../src/voice/estimate';

/** 内存存储 (node 环境没有 localStorage) */
function memoryStorage(initial: string | null = null): SampleStorage & { value: string | null } {
  return {
    value: initial,
    read() {
      return this.value;
    },
    write(text: string) {
      this.value = text;
    },
  };
}

/** 不带持久化的估算器 */
function fresh(): DurationEstimator {
  return new DurationEstimator(null);
}

describe('先验', () => {
  it('没有样本时用该步数的先验 (x4 十六字约 3 秒)', () => {
    const estimator = fresh();
    const estimate = estimator.estimate(4, 16);
    expect(estimate).toBeGreaterThan(2500);
    expect(estimate).toBeLessThan(3600);
  });

  it('步数越大预估越长, 且桶与桶之间互不影响', () => {
    const estimator = fresh();
    estimator.observe(4, 16, 3000);
    // x32 没有任何样本, 仍是自己的先验 (不会因为 x4 很快就被拉低)
    expect(estimator.estimate(32, 16)).toBeGreaterThan(30000);
    expect(estimator.estimate(4, 16)).toBeCloseTo(3000, -2);
  });
});

describe('样本不足 (1~2 个)', () => {
  it('一个样本就能整体纠偏: 覆盖掉先验的量级偏差', () => {
    const estimator = fresh();
    const before = estimator.estimate(4, 16);
    estimator.observe(4, 16, before * 10);
    // 实测是先验的 10 倍 -> 预估也要跟着涨到十倍量级
    expect(estimator.estimate(4, 16)).toBeCloseTo(before * 10, -3);
  });

  it('纠偏保留先验的斜率形状 (字数越多预估越长)', () => {
    const estimator = fresh();
    estimator.observe(32, 20, 20000);
    expect(estimator.estimate(32, 40)).toBeGreaterThan(estimator.estimate(32, 20));
  });

  it('无效耗时不计入', () => {
    const estimator = fresh();
    estimator.observe(4, 10, 0);
    estimator.observe(4, 10, Number.NaN);
    expect(estimator.sampleCount(4)).toBe(0);
  });
});

describe('最小二乘拟合 (≥3 个)', () => {
  it('样本足够时拟合出「固定开销 + 每字耗时」', () => {
    const estimator = fresh();
    // 斜率 100ms/字, 截距 1000ms
    estimator.observe(8, 10, 2000);
    estimator.observe(8, 20, 3000);
    estimator.observe(8, 30, 4000);
    expect(estimator.estimate(8, 10)).toBeCloseTo(2000, -2);
    expect(estimator.estimate(8, 50)).toBeCloseTo(6000, -2);
  });

  it('字数几乎一致时沿用先验斜率, 只校准截距', () => {
    const estimator = fresh();
    estimator.observe(4, 16, 3000);
    estimator.observe(4, 16, 3200);
    estimator.observe(4, 16, 3100);
    const { constant, perChar } = estimator.coefficients(4);
    expect(perChar).toBe(130);
    expect(constant).toBeCloseTo(3100 - 130 * 16, -2);
  });
});

describe('离群值', () => {
  it('只剔除偏高的离群值, 拟合结果不被它带偏', () => {
    const estimator = fresh();
    estimator.observe(32, 10, 20000);
    estimator.observe(32, 20, 30000);
    estimator.observe(32, 30, 40000);
    // 一次被系统调度拖慢到三分钟的推理
    estimator.observe(32, 20, 180000);
    expect(estimator.estimate(32, 20)).toBeCloseTo(30000, -3);
    expect(estimator.estimate(32, 40)).toBeCloseTo(50000, -3);
  });

  it('偏快的样本不会被剔除 (它只让预估更乐观)', () => {
    const estimator = fresh();
    estimator.observe(4, 10, 2000);
    estimator.observe(4, 20, 3000);
    estimator.observe(4, 30, 4000);
    estimator.observe(4, 15, 500);
    expect(estimator.sampleCount(4)).toBe(4);
  });
});

describe('冷启动样本', () => {
  it('取走标记的那一次不计入样本, 之后恢复正常', () => {
    const estimator = fresh();
    // 控制器在**请求发出前**取标记; 被取消/失败的那次推理同样会取走它
    estimator.skipNextSample();
    expect(estimator.takeColdStart()).toBe(true);
    // 冷启动那次按约定不 observe (含模型加载, 高一个量级), 于是样本里只有后面这一次
    estimator.observe(4, 16, 3000);
    expect(estimator.sampleCount(4)).toBe(1);
    expect(estimator.estimate(4, 16)).toBeCloseTo(3000, -2);
  });

  it('标记只生效一次, 不会一直吃掉后续样本', () => {
    const estimator = fresh();
    estimator.skipNextSample();
    expect(estimator.takeColdStart()).toBe(true);
    // 第一次推理被取消 (没有样本), 标记已经用掉 -> 后面这条正常任务不再被跳过
    expect(estimator.takeColdStart()).toBe(false);
    estimator.observe(4, 16, 3000);
    estimator.observe(4, 16, 3200);
    expect(estimator.sampleCount(4)).toBe(2);
  });

  it('没有标记时 takeColdStart 返回 false', () => {
    expect(fresh().takeColdStart()).toBe(false);
  });
});

describe('持久化', () => {
  it('样本写入存储, 换一个实例仍能读到', () => {
    const storage = memoryStorage();
    const first = new DurationEstimator(storage);
    first.observe(16, 10, 12000);
    first.observe(16, 20, 22000);
    first.observe(16, 30, 32000);

    const second = new DurationEstimator(storage);
    expect(second.sampleCount(16)).toBe(3);
    expect(second.estimate(16, 20)).toBeCloseTo(22000, -2);
  });

  it('存储内容坏掉时当作没有样本, 不抛异常', () => {
    const estimator = new DurationEstimator(memoryStorage('{ 不是 json'));
    expect(estimator.sampleCount(4)).toBe(0);
    expect(estimator.estimate(4, 16)).toBeGreaterThan(0);
  });

  it('版本不匹配的旧数据直接忽略', () => {
    const estimator = new DurationEstimator(memoryStorage(JSON.stringify({ v: 0, buckets: { '4': [[10, 1000, 0]] } })));
    expect(estimator.sampleCount(4)).toBe(0);
  });
});
